import os
import logging
from taf.internal.rpc.pyro.pyro_rpc import PyroRPC
from taf.ue.rpc.mtk.proxy import MTKProxy
from taf.ue.rpc.mtk.mtk_server import MTKPYROServerRunner
from taf.internal.rpc.pyro.sys_command import CygwinCommand
from taf.internal.rpc.pyro.server.feature_package import FeaturePackage


class MTKRPC(PyroRPC):

    def __init__(self):
        super(MTKRPC, self).__init__()
        self._feature_packages = []

    def configure(self, hostname, pyro_port, username=None, password=None,
                  server_dir=None, python_path=None, **kwargs):
        """override"""
        self._feature_packages.extend([self._create_mtk_feature_package(**kwargs), ])
        super(MTKRPC, self).configure(hostname=hostname, pyro_port=pyro_port, username=username, password=password,
                                      server_dir=server_dir, python_path=python_path)

    def _create_mtk_feature_package(self, **kwargs):
        return FeaturePackage(object_id=MTKPYROServerRunner.__name__,
                              server_package_name='taf.ue.rpc.mtk.server',
                              server_code_full_local_path=os.path.abspath(os.path.join(os.path.dirname(__file__),
                                                                                       './server')).replace('\\', '/'),
                              exposed_module_name='mtk_server',
                              exposed_class_name='MTKServer',
                              exposed_class_init_kwargs=kwargs)

    def _get_feature_packages(self):
        return self._feature_packages

    def create_proxy(self, hostname=None, port=None, timeout=600, **kwargs):
        return MTKProxy(self._server.uri, timeout=timeout)

    def _create_server_instance(self):
        return MTKPYROServerRunner(self._env.hostname, self._pyro_port, self.workspace.workspace_dir,
                                   self._env.username, self._env.password,
                                   self.python_path, packages=self._feature_packages)

    def _get_required_packages(self):
        packages = super(MTKRPC, self)._get_required_packages()
        packages.append(('mace', ''))
        return packages

    def _check_environment_prerequisites(self, env):
        super(MTKRPC, self)._check_environment_prerequisites(env)
        self._kill_legacy_pythons(env)

    def _kill_legacy_pythons(self, env):
        """
        sometimes the python wasn't killed even the ssh session died, here to force to kill all python processes
        """
        ps_cmd = "ps -ef |grep python|awk '{print $2}'"
        kill_cmd = "kill {}"
        if env.syscommand is CygwinCommand:
            ps_cmd = "/cygdrive/../bin/ps -ef |/cygdrive/../bin/grep python|/cygdrive/../bin/awk '{print $2}'"
            kill_cmd = "/cygdrive/../bin/kill {}"

        python_pids = env.connection.execute(ps_cmd).split("\r\n")
        logging.info("detected python running {}".format(python_pids))
        for pid in python_pids:
            if pid:
                logging.info("killing python running {}".format(pid))
                env.connection.execute(kill_cmd.format(pid))
